// Auto-generated static member / namespace global storage & cross-platform helpers
void G4_PlatformLog(int prio, const char* tag, const char* fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
#ifdef __ANDROID__
    int androidPrio = (prio >= ANDROID_LOG_VERBOSE && prio <= ANDROID_LOG_SILENT)
                          ? prio
                          : ANDROID_LOG_INFO;
    __android_log_vprint(androidPrio, tag ? tag : "Gangstar4", fmt ? fmt : "", ap);
#else
    std::fprintf(stderr, "[%s] ", tag ? tag : "G4");
    std::vfprintf(stderr, fmt ? fmt : "", ap);
#endif
    va_end(ap);
}

