int glf::Thread::GetSequentialThreadId() {
    if (g4_tls_seq_thread_id == 0) {
        g4_tls_seq_thread_id = g4_next_seq_thread_id.fetch_add(1);
    }
    return g4_tls_seq_thread_id;
}
void glf::Thread::ReleaseSequentialThreadId(int) {}
void glf::Thread::Sleep(unsigned int ms) {
    std::this_thread::sleep_for(std::chrono::milliseconds(ms));
}
void glf::Thread::Yield() {
    std::this_thread::yield();
}
bool glf::Thread::IsMain() {
    return GetSequentialThreadId() == 1;
}


